-- Realignment 2A: granular progression without changing the published v1 rows or maximum power.
-- The migration is deliberately one transaction (Supabase applies each migration transactionally).

-- Expand only upgrade-level domains. Festival licence ranks remain 1..5.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT conrelid::regclass rel, conname FROM pg_constraint
    WHERE contype='c' AND conrelid IN ('public.festival_upgrade_levels'::regclass,'public.festival_upgrade_prerequisites'::regclass,'public.festival_company_upgrades'::regclass)
      AND pg_get_constraintdef(oid) ~ '(level|owned_level).*BETWEEN.*(1|0).*AND 5'
  LOOP EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I',r.rel,r.conname); END LOOP;
END $$;
ALTER TABLE public.festival_upgrade_levels ADD CONSTRAINT festival_upgrade_levels_level_1_50 CHECK(level BETWEEN 1 AND 50);
ALTER TABLE public.festival_upgrade_prerequisites ADD CONSTRAINT festival_upgrade_prerequisites_level_1_50 CHECK(level BETWEEN 1 AND 50), ADD CONSTRAINT festival_upgrade_prerequisite_level_1_50 CHECK(prerequisite_level BETWEEN 1 AND 50);
ALTER TABLE public.festival_company_upgrades ADD CONSTRAINT festival_company_upgrades_owned_level_1_50 CHECK(owned_level BETWEEN 1 AND 50);
ALTER TABLE public.festival_upgrade_purchase_operations ADD CONSTRAINT festival_upgrade_purchase_requested_level_1_50 CHECK(requested_level BETWEEN 1 AND 50) NOT VALID;

INSERT INTO public.festival_upgrade_catalogue_versions(version,status,effective_from,admin_notes)
VALUES(2,'draft',now(),'Realignment 2A: 50 levels; v1 milestone economics and effects retained');

-- Each old price/build duration is divided exactly across ten rows. Remainders are
-- assigned to the earliest rows. Upkeep/effects interpolate from the preceding
-- milestone and equal v1 exactly at 10,20,30,40,50.
WITH expanded AS (
 SELECT l.*,g.n,l.level*10 AS milestone,(l.level-1)*10+g.n AS new_level,
   coalesce(prev.weekly_upkeep_minor,0) prev_upkeep,
   coalesce(prev.effects,'{"capacity":0,"qualityBasisPoints":0,"riskReductionBasisPoints":0,"revenueBasisPoints":0}'::jsonb) prev_effects
 FROM public.festival_upgrade_levels l
 LEFT JOIN public.festival_upgrade_levels prev ON prev.catalogue_version=1 AND prev.category_key=l.category_key AND prev.level=l.level-1
 CROSS JOIN generate_series(1,10) g(n) WHERE l.catalogue_version=1
)
INSERT INTO public.festival_upgrade_levels(catalogue_version,category_key,level,level_name,purchase_cost_minor,weekly_upkeep_minor,build_duration,minimum_licence_tier,minimum_company_reputation,effects,effective_from,admin_notes)
SELECT 2,category_key,new_level,
 (ARRAY['Basic','Established','Professional','Major','World Class'])[ceil(new_level/10.0)::int],
 purchase_cost_minor/10 + CASE WHEN n<=purchase_cost_minor%10 THEN 1 ELSE 0 END,
 prev_upkeep + ((weekly_upkeep_minor-prev_upkeep)*n)/10,
 make_interval(secs=>(extract(epoch FROM build_duration)::bigint/10 + CASE WHEN n<=extract(epoch FROM build_duration)::bigint%10 THEN 1 ELSE 0 END)::double precision),
 minimum_licence_tier,minimum_company_reputation,
 jsonb_build_object(
  'capacity',(prev_effects->>'capacity')::int+(((effects->>'capacity')::int-(prev_effects->>'capacity')::int)*n)/10,
  'qualityBasisPoints',(prev_effects->>'qualityBasisPoints')::int+(((effects->>'qualityBasisPoints')::int-(prev_effects->>'qualityBasisPoints')::int)*n)/10,
  'riskReductionBasisPoints',(prev_effects->>'riskReductionBasisPoints')::int+(((effects->>'riskReductionBasisPoints')::int-(prev_effects->>'riskReductionBasisPoints')::int)*n)/10,
  'revenueBasisPoints',(prev_effects->>'revenueBasisPoints')::int+(((effects->>'revenueBasisPoints')::int-(prev_effects->>'revenueBasisPoints')::int)*n)/10),
 now(),'Generated deterministically from immutable v1 milestone '||level
FROM expanded;

-- Licence eligibility requirements refer to the equivalent v2 milestone.
UPDATE public.festival_licence_tiers SET requirements=(SELECT jsonb_object_agg(key,(value::int*10)) FROM jsonb_each_text(requirements));

-- Validate catalogue coverage, parity, and monotonic interpolation before any mutable ownership changes.
DO $$ DECLARE bad int; BEGIN
 IF (SELECT count(*) FROM public.festival_upgrade_categories WHERE active)<>11 THEN RAISE EXCEPTION 'v2 requires exactly eleven categories'; END IF;
 SELECT count(*) INTO bad FROM (SELECT c.key FROM public.festival_upgrade_categories c LEFT JOIN public.festival_upgrade_levels l ON l.catalogue_version=2 AND l.category_key=c.key AND l.active AND l.retired_at IS NULL WHERE c.active GROUP BY c.key HAVING count(*)<>50 OR min(l.level)<>1 OR max(l.level)<>50 OR count(DISTINCT l.level)<>50) x;
 IF bad<>0 OR (SELECT count(*) FROM public.festival_upgrade_levels WHERE catalogue_version=2 AND active)=0 THEN RAISE EXCEPTION 'v2 catalogue coverage invalid'; END IF;
 IF EXISTS(SELECT 1 FROM public.festival_upgrade_levels l WHERE catalogue_version=2 AND purchase_cost_minor<=0) THEN RAISE EXCEPTION 'v2 non-positive cost'; END IF;
 IF EXISTS(SELECT 1 FROM public.festival_upgrade_levels a JOIN public.festival_upgrade_levels b ON b.catalogue_version=2 AND b.category_key=a.category_key AND b.level=a.level+1 WHERE a.catalogue_version=2 AND (b.weekly_upkeep_minor<a.weekly_upkeep_minor OR (b.effects->>'capacity')::int<(a.effects->>'capacity')::int OR (b.effects->>'qualityBasisPoints')::int<(a.effects->>'qualityBasisPoints')::int OR (b.effects->>'riskReductionBasisPoints')::int<(a.effects->>'riskReductionBasisPoints')::int OR (b.effects->>'revenueBasisPoints')::int<(a.effects->>'revenueBasisPoints')::int)) THEN RAISE EXCEPTION 'v2 values are not monotonic'; END IF;
 IF EXISTS(SELECT 1 FROM public.festival_upgrade_levels old WHERE old.catalogue_version=1 AND ((SELECT sum(n.purchase_cost_minor) FROM public.festival_upgrade_levels n WHERE n.catalogue_version=2 AND n.category_key=old.category_key AND n.level BETWEEN (old.level-1)*10+1 AND old.level*10)<>old.purchase_cost_minor OR (SELECT n.weekly_upkeep_minor<>old.weekly_upkeep_minor OR n.effects<>old.effects FROM public.festival_upgrade_levels n WHERE n.catalogue_version=2 AND n.category_key=old.category_key AND n.level=old.level*10))) THEN RAISE EXCEPTION 'v2 milestone parity failure'; END IF;
END $$;

-- Do not guess corrupt/ambiguous ownership. Preserve it for review and abort publication
-- if an invalid mutable row exists, rather than silently granting value.
INSERT INTO public.festival_upgrade_legacy_migrations(festival_company_id,source_table,source_value,category_key,canonical_level,mapping_version,mapping_quality,requires_review)
SELECT festival_company_id,'festival_company_upgrades_v1_review',to_jsonb(u),category_key,NULL,2,'ambiguous',true FROM public.festival_company_upgrades u
WHERE catalogue_version<>1 OR owned_level NOT BETWEEN 1 AND 5 OR active_level NOT BETWEEN 0 AND owned_level ON CONFLICT DO NOTHING;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.festival_company_upgrades WHERE catalogue_version<>1 OR owned_level NOT BETWEEN 1 AND 5 OR active_level NOT BETWEEN 0 AND owned_level) THEN RAISE EXCEPTION 'ambiguous Festival ownership recorded for admin review'; END IF; END $$;

WITH before_rows AS (SELECT *,to_jsonb(u) before_value FROM public.festival_company_upgrades u WHERE catalogue_version=1), changed AS (
 UPDATE public.festival_company_upgrades u SET catalogue_version=2,owned_level=u.owned_level*10,active_level=u.active_level*10,updated_at=u.updated_at FROM before_rows b WHERE u.id=b.id
 RETURNING u.*,b.before_value
)
INSERT INTO public.festival_upgrade_audit(festival_company_id,event_type,reason,before_value,after_value)
SELECT festival_company_id,'catalogue_v2_ownership_migrated','Realignment 2A milestone mapping; no finance movement or aggregate version increment',before_value,to_jsonb(changed)-'before_value' FROM changed;

UPDATE public.festival_upgrade_catalogue_versions SET status='retired',retired_at=now(),admin_notes=coalesce(admin_notes,'')||'; historical v1 retained unchanged' WHERE version=1;
UPDATE public.festival_upgrade_catalogue_versions SET status='published',published_at=now() WHERE version=2;

CREATE OR REPLACE FUNCTION public._festival_effective_level(owned int,active int,missed int) RETURNS int LANGUAGE sql IMMUTABLE AS $$SELECT CASE WHEN missed>=4 THEN greatest(0,least(active,owned-10)) ELSE active END$$;

CREATE OR REPLACE FUNCTION public._festival_upgrade_purchase_window(c uuid,clock_at timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 WITH recent AS (SELECT completed_at FROM public.festival_upgrade_purchase_operations WHERE festival_company_id=c AND status='succeeded' AND financial_transaction_id IS NOT NULL AND completed_at>clock_at-interval '30 days'), x AS (SELECT count(*)::int used,min(completed_at) oldest FROM recent)
 SELECT jsonb_build_object('limit',2,'used',least(used,2),'remaining',greatest(0,2-used),'windowDays',30,'serverNow',clock_at,'nextAvailableAt',CASE WHEN used>=2 THEN oldest+interval '30 days' END) FROM x $$;

CREATE OR REPLACE FUNCTION public._festival_upgrade_category_json(c uuid,k text,v int) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 WITH base AS (SELECT cat.*,coalesce(u.owned_level,0) owned,coalesce(u.active_level,0) active_level,coalesce(u.missed_upkeep_weeks,0) missed,coalesce(u.status,'not_installed') upgrade_status,coalesce(fc.upgrade_delinquent,false) company_delinquent,coalesce(a.available_balance_minor,0) balance FROM public.festival_upgrade_categories cat LEFT JOIN public.festival_company_upgrades u ON u.festival_company_id=c AND u.category_key=cat.key LEFT JOIN public.festival_companies fc ON fc.id=c LEFT JOIN public.financial_accounts a ON a.owner_type='company' AND a.owner_id=fc.company_id AND a.is_primary WHERE cat.key=k), data AS (SELECT b.*,public._festival_effective_level(owned,active_level,missed) effective,n.*,cur.weekly_upkeep_minor current_upkeep,cur.effects current_effects FROM base b LEFT JOIN public.festival_upgrade_levels cur ON cur.catalogue_version=v AND cur.category_key=b.key AND cur.level=public._festival_effective_level(owned,active_level,missed) LEFT JOIN public.festival_upgrade_levels n ON n.catalogue_version=v AND n.category_key=b.key AND n.level=b.owned+1)
 SELECT jsonb_build_object('key',key,'displayName',display_name,'description',description,'ownedLevel',owned,'activeLevel',active_level,'effectiveLevel',effective,'maximumLevel',50,'bandKey',lower(replace((ARRAY['Basic','Established','Professional','Major','World Class'])[least(5,greatest(1,ceil(greatest(owned,1)/10.0)::int))],' ','_')),'bandName',(ARRAY['Basic','Established','Professional','Major','World Class'])[least(5,greatest(1,ceil(greatest(owned,1)/10.0)::int))],'bandStartLevel',((least(5,greatest(1,ceil(greatest(owned,1)/10.0)::int))-1)*10)+1,'bandEndLevel',least(5,greatest(1,ceil(greatest(owned,1)/10.0)::int))*10,'nextMilestoneLevel',CASE WHEN owned<50 THEN least(50,((owned/10)+1)*10) END,'nextMilestoneName',CASE WHEN owned<50 THEN (ARRAY['Basic','Established','Professional','Major','World Class'])[least(5,(owned/10)+1)] END,'levelsUntilMilestone',CASE WHEN owned<50 THEN least(50,((owned/10)+1)*10)-owned END,'status',upgrade_status,'currentUpkeepMinor',coalesce(current_upkeep,0),'nextLevel',level,'nextCostMinor',purchase_cost_minor,'nextUpkeepMinor',weekly_upkeep_minor,'buildDurationHours',extract(epoch from build_duration)::bigint/3600,'effects',coalesce(current_effects,'{}'),'nextEffects',effects,'effectDelta',coalesce(effects,'{}')-ARRAY[]::text[],'missingRequirements',coalesce((SELECT jsonb_agg(blocker) FROM (SELECT jsonb_build_object('code','FESTIVAL_UPGRADE_LICENCE_REQUIRED','message','A current Festival licence tier '||minimum_licence_tier||' is required.') blocker WHERE minimum_licence_tier>coalesce((SELECT max(t.rank) FROM public.festival_company_licences cl JOIN public.festival_licence_tiers t ON t.key=cl.tier_key WHERE cl.festival_company_id=c AND cl.status='active' AND coalesce(cl.valid_from,'-infinity')<=now() AND coalesce(cl.valid_until,'infinity')>now()),0) UNION ALL SELECT jsonb_build_object('code','FESTIVAL_UPGRADE_REPUTATION_REQUIRED','message','Company reputation '||minimum_company_reputation||' is required.') WHERE minimum_company_reputation>coalesce((SELECT co.reputation_score FROM public.festival_companies f JOIN public.companies co ON co.id=f.company_id WHERE f.id=c),0) UNION ALL SELECT jsonb_build_object('code','FESTIVAL_UPGRADE_PREREQUISITE_MISSING','message','Prerequisite '||p.prerequisite_category_key||' level '||p.prerequisite_level||' is required.') FROM public.festival_upgrade_prerequisites p LEFT JOIN public.festival_company_upgrades pu ON pu.festival_company_id=c AND pu.category_key=p.prerequisite_category_key WHERE p.catalogue_version=v AND p.category_key=k AND p.level=data.level AND coalesce(pu.active_level,0)<p.prerequisite_level) blockers),'[]'::jsonb),'affordable',balance>=coalesce(purchase_cost_minor,0),'construction',jsonb_build_object('status',upgrade_status),'delinquent',company_delinquent OR missed>0) FROM data $$;

CREATE OR REPLACE FUNCTION public.get_festival_company_upgrades(p_festival_company_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_upgrade_actor();v int;fc public.festival_companies%ROWTYPE;clock_at timestamptz:=now();BEGIN SELECT * INTO fc FROM public.festival_companies WHERE id=p_festival_company_id;IF fc.id IS NULL OR NOT public._festival_upgrade_authorised(fc.id,a) THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_ACCESS_DENIED' USING ERRCODE='P0001';END IF;SELECT version INTO v FROM public.festival_upgrade_catalogue_versions WHERE status='published' AND retired_at IS NULL;RETURN jsonb_build_object('festivalCompanyId',fc.id,'catalogueVersion',v,'companyVersion',fc.upgrade_version,'currencyCode','GBP','availableBalanceMinor',coalesce((SELECT available_balance_minor FROM public.financial_accounts WHERE owner_type='company' AND owner_id=fc.company_id AND is_primary),0),'purchaseWindow',public._festival_upgrade_purchase_window(fc.id,clock_at),'categories',(SELECT jsonb_agg(public._festival_upgrade_category_json(fc.id,key,v) ORDER BY display_order) FROM public.festival_upgrade_categories WHERE active),'licence',public.get_festival_licence_progress(fc.id));END$$;

CREATE OR REPLACE FUNCTION public.get_festival_upgrade_purchase_preview(p_festival_company_id uuid,p_category_key text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE s jsonb;c jsonb;reasons jsonb:='[]';BEGIN s:=public.get_festival_company_upgrades(p_festival_company_id);SELECT x INTO c FROM jsonb_array_elements(s->'categories') x WHERE x->>'key'=p_category_key;IF c IS NULL THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_CATEGORY_NOT_FOUND' USING ERRCODE='P0001';END IF;IF c->'nextLevel'='null'::jsonb THEN reasons:=reasons||'"FESTIVAL_UPGRADE_COMPLETE"'::jsonb; END IF;IF NOT (c->>'affordable')::boolean THEN reasons:=reasons||'"FESTIVAL_UPGRADE_INSUFFICIENT_FUNDS"'::jsonb;END IF;IF (c->>'delinquent')::boolean THEN reasons:=reasons||'"FESTIVAL_UPGRADE_DELINQUENT"'::jsonb;END IF;IF (s->'purchaseWindow'->>'remaining')::int=0 THEN reasons:=reasons||'"FESTIVAL_UPGRADE_ROLLING_LIMIT_REACHED"'::jsonb;END IF;RETURN jsonb_build_object('category',c,'catalogueVersion',s->'catalogueVersion','companyVersion',s->'companyVersion','purchaseWindow',s->'purchaseWindow','balanceMinor',s->'availableBalanceMinor','remainingBalanceMinor',greatest(0,(s->>'availableBalanceMinor')::bigint-coalesce((c->>'nextCostMinor')::bigint,0)),'eligible',jsonb_array_length(reasons)=0,'reasonCodes',reasons,'licenceImplications','[]'::jsonb);END$$;

-- Serialize idempotency before reading receipts, then serialize the company aggregate.
-- Requirement checks and quota all precede finance_debit_owner.
CREATE OR REPLACE FUNCTION public.purchase_festival_company_upgrade(p_festival_company_id uuid,p_category_key text,p_requested_level integer,p_expected_catalogue_version integer,p_expected_company_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_upgrade_actor();fc public.festival_companies%ROWTYPE;u public.festival_company_upgrades%ROWTYPE;l public.festival_upgrade_levels%ROWTYPE;op public.festival_upgrade_purchase_operations%ROWTYPE;v int;h text;tx uuid;result jsonb;used int;licence_rank int;reputation int;BEGIN h:=encode(digest(jsonb_build_object('company',p_festival_company_id,'category',p_category_key,'level',p_requested_level,'catalogue',p_expected_catalogue_version,'companyVersion',p_expected_company_version)::text,'sha256'),'hex');PERFORM pg_advisory_xact_lock(hashtextextended(a::text||':'||p_idempotency_key::text,0));SELECT * INTO op FROM public.festival_upgrade_purchase_operations WHERE actor_profile_id=a AND idempotency_key=p_idempotency_key;IF op.id IS NOT NULL THEN IF op.payload_hash<>h THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;IF op.status='succeeded' THEN RETURN op.result;END IF;END IF;SELECT * INTO fc FROM public.festival_companies WHERE id=p_festival_company_id FOR UPDATE;IF fc.id IS NULL OR NOT public._festival_upgrade_authorised(fc.id,a) THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_ACCESS_DENIED' USING ERRCODE='P0001';END IF;IF fc.upgrade_delinquent THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_DELINQUENT' USING ERRCODE='P0001';END IF;SELECT version INTO v FROM public.festival_upgrade_catalogue_versions WHERE status='published' AND retired_at IS NULL;IF v<>p_expected_catalogue_version THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_CATALOGUE_CHANGED' USING ERRCODE='P0001';END IF;IF fc.upgrade_version<>p_expected_company_version THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_VERSION_CONFLICT' USING ERRCODE='P0001';END IF;SELECT * INTO u FROM public.festival_company_upgrades WHERE festival_company_id=fc.id AND category_key=p_category_key FOR UPDATE;IF p_requested_level NOT BETWEEN 1 AND 50 OR coalesce(u.owned_level,0)+1<>p_requested_level THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_LEVEL_SEQUENCE_INVALID' USING ERRCODE='P0001';END IF;IF u.status='building' THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_BUILD_IN_PROGRESS' USING ERRCODE='P0001';END IF;SELECT * INTO l FROM public.festival_upgrade_levels WHERE catalogue_version=v AND category_key=p_category_key AND level=p_requested_level AND active AND retired_at IS NULL;IF l.category_key IS NULL THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_LEVEL_NOT_FOUND' USING ERRCODE='P0001';END IF;SELECT coalesce(max(t.rank),0) INTO licence_rank FROM public.festival_company_licences cl JOIN public.festival_licence_tiers t ON t.key=cl.tier_key WHERE cl.festival_company_id=fc.id AND cl.status='active' AND coalesce(cl.valid_from,'-infinity')<=now() AND coalesce(cl.valid_until,'infinity')>now();SELECT coalesce(reputation_score,0) INTO reputation FROM public.companies WHERE id=fc.company_id;IF licence_rank<l.minimum_licence_tier THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_LICENCE_REQUIRED' USING ERRCODE='P0001';END IF;IF reputation<l.minimum_company_reputation THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_REPUTATION_REQUIRED' USING ERRCODE='P0001';END IF;IF EXISTS(SELECT 1 FROM public.festival_upgrade_prerequisites p LEFT JOIN public.festival_company_upgrades x ON x.festival_company_id=fc.id AND x.category_key=p.prerequisite_category_key WHERE p.catalogue_version=v AND p.category_key=p_category_key AND p.level=p_requested_level AND coalesce(x.active_level,0)<p.prerequisite_level) THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_PREREQUISITE_MISSING' USING ERRCODE='P0001';END IF;SELECT count(*) INTO used FROM public.festival_upgrade_purchase_operations WHERE festival_company_id=fc.id AND status='succeeded' AND financial_transaction_id IS NOT NULL AND completed_at>now()-interval '30 days';IF used>=2 THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_ROLLING_LIMIT_REACHED %',public._festival_upgrade_purchase_window(fc.id,now()) USING ERRCODE='P0001';END IF;INSERT INTO public.festival_upgrade_purchase_operations(festival_company_id,actor_profile_id,category_key,requested_level,idempotency_key,payload_hash,status,catalogue_version,company_version,amount_minor) VALUES(fc.id,a,p_category_key,p_requested_level,p_idempotency_key,h,'processing',v,fc.upgrade_version,l.purchase_cost_minor) RETURNING * INTO op;BEGIN tx:=public.finance_debit_owner('company',fc.company_id,l.purchase_cost_minor,'company_expense','Festival upgrade: '||p_category_key,'festival-upgrade:'||op.id,a,jsonb_build_object('categoryKey',p_category_key,'level',p_requested_level,'catalogueVersion',v));EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE '%insufficient%' THEN RAISE EXCEPTION 'FESTIVAL_UPGRADE_INSUFFICIENT_FUNDS' USING ERRCODE='P0001';END IF;RAISE;END;INSERT INTO public.festival_company_upgrades(festival_company_id,category_key,catalogue_version,owned_level,active_level,status,build_started_at,build_completes_at,activated_at) VALUES(fc.id,p_category_key,v,p_requested_level,0,CASE WHEN l.build_duration=interval '0' THEN 'active' ELSE 'building' END,now(),now()+l.build_duration,CASE WHEN l.build_duration=interval '0' THEN now() END) ON CONFLICT(festival_company_id,category_key) DO UPDATE SET catalogue_version=v,owned_level=p_requested_level,status=excluded.status,build_started_at=now(),build_completes_at=excluded.build_completes_at,activated_at=excluded.activated_at,updated_at=now();IF l.build_duration=interval '0' THEN UPDATE public.festival_company_upgrades SET active_level=p_requested_level WHERE festival_company_id=fc.id AND category_key=p_category_key;END IF;UPDATE public.festival_companies SET upgrade_version=upgrade_version+1 WHERE id=fc.id;INSERT INTO public.festival_upgrade_effect_snapshots(purchase_operation_id,festival_company_id,category_key,owned_level,active_level,effective_level,effects,catalogue_version,aggregate_version,snapshot_hash) SELECT op.id,fc.id,p_category_key,owned_level,active_level,public._festival_effective_level(owned_level,active_level,missed_upkeep_weeks),l.effects,v,fc.upgrade_version+1,encode(digest((fc.id::text||p_category_key||p_requested_level||v),'sha256'),'hex') FROM public.festival_company_upgrades WHERE festival_company_id=fc.id AND category_key=p_category_key;INSERT INTO public.festival_upgrade_audit(festival_company_id,actor_profile_id,event_type,after_value) VALUES(fc.id,a,'upgrade_purchased',jsonb_build_object('category',p_category_key,'level',p_requested_level,'transactionId',tx));result:=public.get_festival_company_upgrades(fc.id);UPDATE public.festival_upgrade_purchase_operations SET status='succeeded',financial_transaction_id=tx,result=result,completed_at=now() WHERE id=op.id;RETURN result;END$$;
